import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.ChMUB7od.js";const m=JSON.parse('{"title":"Connect","description":"","frontmatter":{},"headers":[],"relativePath":"developers/connecting.md","filePath":"developers/connecting.md"}'),i={name:"developers/connecting.md"};function r(d,e,n,c,l,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="connect" tabindex="-1">Connect <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Connect&quot;">​</a></h1><p>s32 can talk to a real S32 (<code>--usb</code>) or to an in-process simulator (<code>--loopback</code>). Choose the backend that matches the job.</p><h2 id="usb" tabindex="-1">USB <a class="header-anchor" href="#usb" aria-label="Permalink to &quot;USB&quot;">​</a></h2><p><code>--usb</code> claims the S32 Editor interface. Only one host can hold that interface at a time. Close the web editor before connecting. Firmware applies the same command limits to s32 and to the web editor.</p><p>Claiming the interface is <strong>full device control</strong>: read and overwrite projects, change live mappings, and capture the OLED. There is no password. Trust is physical USB plus local permission to that device node. This is not a network service.</p><p>Before you connect:</p><ol><li>Close the <strong>web editor</strong> (any browser tab using WebUSB).</li><li>Prefer a project you can restore. <code>pull</code> a copy first.</li><li>Destructive commands prompt unless you pass <code>--yes</code>.</li></ol><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>push --activate</code></td><td>Replaces the live project</td></tr><tr><td><code>project delete</code></td><td>Removes a stored project</td></tr><tr><td><code>project load</code></td><td>Replaces the live editing session</td></tr><tr><td><code>rack clear</code></td><td>Removes every device in the rack</td></tr><tr><td><code>globals set</code></td><td>Writes device-wide settings</td></tr></tbody></table><p><code>--script</code> skips prompts so a script cannot hang on stdin. Pass <code>--yes</code> for one-shot destructive commands in CI or pipes. <code>--script</code> does not unlock panel-only actions; firmware still rejects them. <code>view nav</code> only jumps to hub screens (Perform, Main, Racks, …) and does not push the panel Back stack.</p><h2 id="simulator" tabindex="-1">Simulator <a class="header-anchor" href="#simulator" aria-label="Permalink to &quot;Simulator&quot;">​</a></h2><p><code>--loopback</code> does not touch hardware. Use it for examples, CI, and trying commands before you run them on a device.</p><table tabindex="0"><thead><tr><th></th><th><code>--loopback</code></th><th><code>--usb</code></th></tr></thead><tbody><tr><td>Target</td><td>In-process simulator</td><td>Attached S32</td></tr><tr><td>Persistence</td><td>This process only</td><td>On-device storage</td></tr><tr><td>Device types</td><td>Small fixture set</td><td>Live firmware tables</td></tr><tr><td>Safe for experiments</td><td>Yes</td><td>Back up first</td></tr></tbody></table><p>Default: <code>--usb</code> when a board is present; <code>--loopback</code> when it is not. Pass either flag when you want to be explicit.</p><h2 id="scripts" tabindex="-1">Scripts <a class="header-anchor" href="#scripts" aria-label="Permalink to &quot;Scripts&quot;">​</a></h2><p>Save a file of <code>command args…</code> lines. <code>#</code> starts a comment. The run exits non-zero if a line fails.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session.script</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session.script</span></span></code></pre></div><p>See <a href="./simulator">Simulator and scripts</a>.</p>`,17)])])}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
